{
  "name": "Modbus TCP客户端",
  "name_en": "Modbus TCP Client",
  "manufacturer": "",
  "description": "用于通过 Modbus TCP 协议连接并访问兼容设备的通用通信客户端。它常用于实验室自动化中接入 PLC、远程 I/O、传感器网关、电源或过程控制仪表，以读取线圈、离散输入和寄存器数据，并写入控制命令。",
  "description_en": "A general-purpose communication client for connecting to and accessing Modbus TCP compatible devices. It is commonly used in laboratory automation to interface with PLCs, remote I/O modules, sensor gateways, power supplies, or process instruments, allowing coil, discrete input, and register data to be read and control values to be written.",
  "tag_hints": [
    "Modbus TCP",
    "industrial Ethernet",
    "PLC communication",
    "remote I/O",
    "coil/register access",
    "process control instrumentation"
  ],
  "actions": [
    {
      "action_name": "auto-version",
      "description": "获取客户端版本",
      "description_en": "Get the client version."
    },
    {
      "action_name": "auto-last_error",
      "description": "获取最近一次错误代码",
      "description_en": "Get the last error code."
    },
    {
      "action_name": "auto-last_error_as_txt",
      "description": "获取最近一次错误的文本说明",
      "description_en": "Get the text description of the last error."
    },
    {
      "action_name": "auto-last_except",
      "description": "获取最近一次 Modbus 异常代码",
      "description_en": "Get the last Modbus exception code."
    },
    {
      "action_name": "auto-last_except_as_txt",
      "description": "获取最近一次 Modbus 异常的简短文本说明",
      "description_en": "Get the short text description of the last Modbus exception."
    },
    {
      "action_name": "auto-last_except_as_full_txt",
      "description": "获取最近一次 Modbus 异常的详细文本说明",
      "description_en": "Get the full text description of the last Modbus exception."
    },
    {
      "action_name": "auto-host",
      "description": "获取/设置目标 Modbus TCP 服务器地址",
      "description_en": "Get/set the target Modbus TCP server host address."
    },
    {
      "action_name": "auto-port",
      "description": "获取/设置目标 TCP 端口",
      "description_en": "Get/set the target TCP port."
    },
    {
      "action_name": "auto-unit_id",
      "description": "获取/设置 Modbus 单元标识符",
      "description_en": "Get/set the Modbus unit identifier."
    },
    {
      "action_name": "auto-timeout",
      "description": "获取/设置请求超时时间",
      "description_en": "Get/set the request timeout."
    },
    {
      "action_name": "auto-auto_open",
      "description": "获取/设置是否在请求时自动建立 TCP 连接",
      "description_en": "Get/set whether to automatically open the TCP connection when making a request."
    },
    {
      "action_name": "auto-auto_close",
      "description": "获取/设置是否在每次请求后自动关闭 TCP 连接",
      "description_en": "Get/set whether to automatically close the TCP connection after each request."
    },
    {
      "action_name": "auto-is_open",
      "description": "获取 TCP 连接是否已打开",
      "description_en": "Get whether the TCP connection is open."
    },
    {
      "action_name": "auto-open",
      "description": "打开到 Modbus 服务器的 TCP 连接",
      "description_en": "Open the TCP connection to the Modbus server."
    },
    {
      "action_name": "auto-close",
      "description": "关闭当前 TCP 连接",
      "description_en": "Close the current TCP connection."
    },
    {
      "action_name": "auto-custom_request",
      "description": "发送自定义 Modbus 请求 PDU",
      "description_en": "Send a custom Modbus request PDU."
    },
    {
      "action_name": "auto-read_coils",
      "description": "读取线圈状态",
      "description_en": "Read coil states."
    },
    {
      "action_name": "auto-read_discrete_inputs",
      "description": "读取离散输入状态",
      "description_en": "Read discrete input states."
    },
    {
      "action_name": "auto-read_holding_registers",
      "description": "读取保持寄存器",
      "description_en": "Read holding registers."
    },
    {
      "action_name": "auto-read_input_registers",
      "description": "读取输入寄存器",
      "description_en": "Read input registers."
    },
    {
      "action_name": "auto-read_device_identification",
      "description": "读取设备标识信息",
      "description_en": "Read device identification information."
    },
    {
      "action_name": "auto-write_single_coil",
      "description": "写入单个线圈",
      "description_en": "Write a single coil."
    },
    {
      "action_name": "auto-write_single_register",
      "description": "写入单个保持寄存器",
      "description_en": "Write a single holding register."
    },
    {
      "action_name": "auto-write_multiple_coils",
      "description": "写入多个线圈",
      "description_en": "Write multiple coils."
    },
    {
      "action_name": "auto-write_multiple_registers",
      "description": "写入多个保持寄存器",
      "description_en": "Write multiple holding registers."
    },
    {
      "action_name": "auto-write_read_multiple_registers",
      "description": "写入多个寄存器并读取多个寄存器",
      "description_en": "Write multiple registers and read multiple registers."
    },
    {
      "action_name": "auto-on_tx_rx",
      "description": "处理或记录每次发送/接收的 Modbus 帧",
      "description_en": "Handle or log each transmitted/received Modbus frame."
    }
  ]
}

